"use client"

import {
  ScrollArea as ScrollAreaRoot,
  ScrollAreaContent,
  ScrollAreaCorner,
  ScrollAreaViewport,
} from "@ui-sdk/react/scroll-area"

import { cn } from "@/lib/utils"

import { ScrollBar } from "./scroll-bar"
import type { ScrollAreaProps } from "./scroll-area.types"
import { scrollAreaViewportClasses } from "./scroll-area.variants"

export function ScrollArea({ className, children, orientation = "vertical", viewportProps, ...props }: ScrollAreaProps) {
  const { className: viewportClassName, ...restViewportProps } = viewportProps ?? {}

  return (
    <ScrollAreaRoot className={cn("relative", className)} {...props}>
      <ScrollAreaViewport
        className={cn(scrollAreaViewportClasses, typeof viewportClassName === "string" ? viewportClassName : undefined)}
        {...restViewportProps}
      >
        <ScrollAreaContent>{children}</ScrollAreaContent>
      </ScrollAreaViewport>
      {orientation !== "horizontal" && <ScrollBar orientation="vertical" />}
      {orientation !== "vertical" && <ScrollBar orientation="horizontal" />}
      {orientation === "both" && <ScrollAreaCorner />}
    </ScrollAreaRoot>
  )
}

import type { ComponentProps } from "react"
import type {
  ScrollArea as ScrollAreaRoot,
  ScrollAreaScrollbar,
  ScrollAreaViewport,
} from "@ui-sdk/react/scroll-area"

export type ScrollAreaOrientation = "vertical" | "horizontal" | "both"

export type ScrollAreaProps = Omit<ComponentProps<typeof ScrollAreaRoot>, "className"> & {
  className?: string
  /** Which axes get a scrollbar. Defaults to "vertical". */
  orientation?: ScrollAreaOrientation
  /** Props for the scrollable viewport, e.g. `role` and `aria-label` to name the region. */
  viewportProps?: ComponentProps<typeof ScrollAreaViewport>
}

export type ScrollBarProps = Omit<ComponentProps<typeof ScrollAreaScrollbar>, "className"> & {
  className?: string
}

"use client"

import { ScrollAreaScrollbar, ScrollAreaThumb } from "@ui-sdk/react/scroll-area"

import { cn } from "@/lib/utils"

import type { ScrollBarProps } from "./scroll-area.types"
import { scrollBarClasses, scrollBarThumbClasses } from "./scroll-area.variants"

export function ScrollBar({ className, orientation = "vertical", ...props }: ScrollBarProps) {
  return (
    <ScrollAreaScrollbar orientation={orientation} className={cn(scrollBarClasses, className)} {...props}>
      <ScrollAreaThumb className={scrollBarThumbClasses} />
    </ScrollAreaScrollbar>
  )
}
